.wao-image-wrapper {
  position: relative;
  display: block;
  width: fit-content;
  max-width: 100%;
}

.wao-image-wrapper img {
  display: block;
  max-width: 100%;
  width: auto;
}

.wao-image-overlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(148, 163, 184, 0.32);
  backdrop-filter: blur(1px);
  border-radius: inherit;
  z-index: 70;
  pointer-events: none;
}

.wao-image-overlay__spinner {
  width: 28px;
  height: 28px;
  border-radius: 999px;
  border: 3px solid rgba(255, 255, 255, 0.45);
  border-top-color: rgba(255, 255, 255, 0.95);
  animation: wao-image-spin 0.8s linear infinite;
  box-shadow: 0 4px 12px rgba(15, 23, 42, 0.16);
}

.wao-image-tools {
  position: absolute;
  top: 12px;
  right: 12px;
  display: flex;
  gap: 8px;
  z-index: 99;
}

.wao-image-tools__button {
  width: 32px;
  height: 32px;
  border: 1px solid rgba(255, 255, 255, 0.24);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.92);
  color: #16181d;
  backdrop-filter: blur(6px);
  cursor: pointer;
  font-size: 14px;
  line-height: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 8px 18px rgba(15, 23, 42, 0.12);
  transition: background-color 0.15s ease, border-color 0.15s ease, transform 0.15s ease, color 0.15s ease;
}

.wao-image-tools__button:hover:not(:disabled) {
  background: rgba(245, 245, 250, 0.98);
  border-color: rgba(139, 92, 246, 0.5);
  color: #6d28d9;
  transform: scale(1.05);
}

.wao-image-tools__button:active:not(:disabled) {
  background: rgba(235, 235, 242, 0.98);
  transform: scale(1);
}

.wao-image-tools__button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none;
}

.wao-image-tools__button svg {
  width: 14px;
  height: 14px;
}

.wao-image-wrapper.is-regenerating .wao-image-tools__button {
  pointer-events: none;
  opacity: 0.35;
}

@keyframes wao-image-spin {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

